using System;
using BepInEx.Configuration;
using Comfort.Common;
using EFT;
using EFT.HealthSystem;
using UnityEngine;
namespace LocalSpt5Esp;
internal static class GlobalKillFeed {
 static ConfigEntry<bool> enabled=null!,ai=null!,environment=null!;static ConfigEntry<float> duration=null!;static ConfigEntry<int> lines=null!,font=null!;
 static readonly RaidKillBuffer feed=new();static IntPtr world;static GUIStyle? style;static float nextError;
 internal static void Initialize(){const string section="52. 全战局击杀";enabled=FeatureConfig.Bind(section,"World kill feed","全战局击杀信息",true,"独立于玩家命中提示，显示确认死亡；可显示 AI 击杀 AI。");ai=FeatureConfig.Bind(section,"Include AI kills","显示 AI 击杀 AI",true);environment=FeatureConfig.Bind(section,"Include unknown deaths","显示环境或归属未知的死亡",true);duration=FeatureConfig.Bind(section,"Kill feed duration","击杀信息保留秒数",8f,"",new AcceptableValueRange<float>(2,30));lines=FeatureConfig.Bind(section,"Kill feed rows","击杀信息最多行数",6,"",new AcceptableValueRange<int>(1,12));font=FeatureConfig.Bind(section,"Kill feed font","击杀信息字号",16,"",new AcceptableValueRange<int>(11,28));}
 internal static void Reset(){feed.Clear();world=IntPtr.Zero;}
 internal static void AfterKill(ActiveHealthController __instance,bool __runOriginal){if(!__runOriginal||enabled?.Value!=true)return;try{if(__instance.IsAlive||__instance.Player==null)return;Record(__instance.Player,null,EBodyPart.Common);}catch(Exception e){Warn(e);}}
 static string Name(Player? actor,bool local)=>local?"玩家":actor==null?"未知单位":BossLabels.Label(actor).Replace('\n',' ').Replace('\r',' ');
 internal static void Record(Player victim,IPlayer? attacker,EBodyPart part){if(enabled?.Value!=true||!RaidClock.Active||victim.HealthController?.IsAlive!=false)return;try{var current=Singleton<GameWorld>.Instance;if(current?.MainPlayer==null)return;if(world!=current.Pointer){Reset();world=current.Pointer;}var killer=attacker?.TryCast<Player>();bool localVictim=victim.ProfileId==current.MainPlayer.ProfileId,localKiller=attacker?.ProfileId==current.MainPlayer.ProfileId;bool known=attacker!=null&&!string.IsNullOrEmpty(attacker.ProfileId);string killerName=known?Name(killer,localKiller):"环境／未知";string victimName=Name(victim,localVictim);feed.Stage(new(victim.ProfileId,attacker?.ProfileId??"",victimName,killerName,part==EBodyPart.Common?"":part.ToString(),localVictim||localKiller,known,Time.unscaledTime));}catch(Exception e){Warn(e);}}
 internal static void Tick(GameWorld? current){if(current==null||world!=IntPtr.Zero&&world!=current.Pointer){Reset();return;}if(!enabled.Value){feed.Clear();return;}feed.Update(Time.unscaledTime,duration.Value,lines.Value,ai.Value,environment.Value);}
 internal static void Draw(){if(!enabled.Value||feed.Entries.Count==0||!RaidClock.Active)return;style??=new GUIStyle(GUI.skin.label){alignment=TextAnchor.MiddleLeft,richText=false,wordWrap=false,clipping=TextClipping.Clip};style.fontSize=font.Value;float row=font.Value+13;float width=Math.Min(640,Screen.width-24);using var windowOpacity=InterfaceMenu.BeginWindow("allkills");var panel=InterfaceMenu.Place("allkills",new Rect(Screen.width-width-12,Screen.height*.49f,width,row*feed.Entries.Count));var old=GUI.color;try{for(int i=feed.Entries.Count-1,visible=0;i>=0;i--,visible++){var item=feed.Entries[i];float alpha=Math.Clamp((float)(duration.Value-Time.unscaledTime+item.Time)/.6f,0,1);var rect=new Rect(panel.x,panel.y+visible*row,panel.width,row-3);if(rect.yMax>Screen.height-30)break;InterfaceMenu.Panel(rect,alpha);float cell=(rect.width-50)/2;GUI.color=new Color(.9f,.94f,1,alpha);GUI.Label(new Rect(rect.x+8,rect.y,cell,rect.height),I18n.Text(item.KillerName),style);GUI.color=new Color(.7f,.8f,.9f,alpha);GUI.Label(new Rect(rect.x+cell+12,rect.y,30,rect.height),I18n.Text("→"),style);GUI.color=new Color(1,.65f,.55f,alpha);GUI.Label(new Rect(rect.x+cell+46,rect.y,cell,rect.height),I18n.Text(item.VictimName),style);}}finally{GUI.color=old;}}
 static void Warn(Exception error){if(Time.unscaledTime<nextError)return;nextError=Time.unscaledTime+15;Plugin.Self.Log.LogWarning("World kill feed: "+error.Message);}
}
